-- V1.9.3 — Revue de suivi (25 November 2026). A weekly review for the coach: for each athlete, the case to handle, the next action and its
-- source, then a next proposal PREPARED from an existing template (or a past proposal), previewed, and sent only when the coach sends it.
-- Behind the server flag screens.coach_review (absent = closed). It REUSES what exists and copies nothing private:
--   the sharing link (public.coach_links: scope, pause of capacity, revocation) decides every read and every send, at that moment;
--   the follow-up states of V1.9.1 (private.titan_coach_followup_row: dates planned, moved and done, gaps, waits, history);
--   the feedback of V1.9.2 (private.titan_coach_feedback: sessions without feedback, adjustments pending or answered);
--   the weekly check-in of V11-81 (private.titan_coach_checkins), only when the athlete shared it with THIS link;
--   the coach's templates (private.titan_coach_templates) and the portal's rules for a proposal (date window, 500 per link);
--   a proposal sent from the review is an ordinary public.coach_assignments row (status proposed): the athlete answers it in their own space
--   (Web, Android « Mes suivis de coaching ») exactly as before, and its decision shows in the review of the following week.
-- New: private.titan_coach_review_drafts, one prepared proposal per link and week (state draft, sent or discarded). Preparing again the same
-- week resumes the draft instead of creating a second one; sending is idempotent (a draft is sent once, a second send answers « already »,
-- and a draft identical to a proposal already open on the link is attached to it instead of duplicating it). The review card is computed at
-- every read: a paused link shows its name and « en pause » only, a revoked link disappears; a revocation or a pause between the read and the
-- send refuses the send (SHARING_UNAVAILABLE, COACH_CAPACITY_PAUSED) and the draft stays unsent.
-- No action writes public.training_logs, a check-in or a note. No XP, no credit, no notification. Additive. The caller owns the
-- transaction: never BEGIN/COMMIT here.
-- Rollback: drop function public.titan_coach_review_v1(text, jsonb), private.titan_coach_review_measure(),
-- private.titan_coach_review_card(public.coach_links, date), private.titan_coach_review_draft_row(private.titan_coach_review_drafts, public.coach_links);
-- drop table private.titan_coach_review_drafts; re-apply private.titan_export_extras_v1 of 20261202090000.

create table if not exists private.titan_coach_review_drafts (
  id uuid primary key default gen_random_uuid(),
  link_id uuid not null references public.coach_links(id) on delete cascade,
  coach_id uuid not null references auth.users(id) on delete cascade,
  week_start date not null check (extract(isodow from week_start) = 1 and week_start between '2000-01-03' and '2100-12-27'),
  state text not null default 'draft' check (state in ('draft', 'sent', 'discarded')),
  basis jsonb not null check (jsonb_typeof(basis) = 'object' and basis->>'kind' in ('template', 'proposal', 'blank')),
  content jsonb not null check (jsonb_typeof(content) = 'object'),
  assignment_id uuid references public.coach_assignments(id) on delete set null,
  revision integer not null default 1,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  sent_at timestamptz,
  check ((state = 'sent') = (sent_at is not null))
);
create unique index if not exists titan_coach_review_drafts_open on private.titan_coach_review_drafts (link_id, week_start) where state = 'draft';
create unique index if not exists titan_coach_review_drafts_sent on private.titan_coach_review_drafts (assignment_id) where assignment_id is not null;
create index if not exists titan_coach_review_drafts_link_idx on private.titan_coach_review_drafts (link_id, week_start desc);
alter table private.titan_coach_review_drafts enable row level security;
revoke all on private.titan_coach_review_drafts from public, anon, authenticated;

-- A draft as the coach sees it: content, what changed against its basis (the preview), and whether it can be sent now.
create or replace function private.titan_coach_review_draft_row(d private.titan_coach_review_drafts, l public.coach_links)
returns jsonb language sql stable security definer set search_path = ''
as $function$
  select jsonb_build_object('id', d.id, 'link_id', d.link_id, 'week', d.week_start, 'state', d.state, 'revision', d.revision,
    'basis', d.basis - 'base', 'content', d.content, 'assignment_id', d.assignment_id, 'sent_at', d.sent_at, 'updated_at', d.updated_at,
    'changes', coalesce((select jsonb_agg(jsonb_build_object('field', f, 'before', d.basis#>>array['base', f], 'after', d.content->>f) order by o)
                           from unnest(array['title', 'sport', 'planned_date', 'instructions']) with ordinality u(f, o)
                          where (d.content->>f) is distinct from (d.basis#>>array['base', f])), '[]'::jsonb),
    'can_send', d.state = 'draft' and l.revoked_at is null and private.titan_coach_link_active(l.id))
$function$;
revoke all on function private.titan_coach_review_draft_row(private.titan_coach_review_drafts, public.coach_links) from public, anon, authenticated;

-- One athlete of the review, for the week starting p_week (Paris Monday): the past week [p_week - 7, p_week - 1] and the coming one
-- [p_week, p_week + 6]. Everything is read through the link's current contract (the V1.9.1 rows already apply it).
create or replace function private.titan_coach_review_card(l public.coach_links, p_week date)
returns jsonb language plpgsql stable security definer set search_path = ''
as $function$
declare
  v_today date := (now() at time zone 'Europe/Paris')::date; v_name text; v_items jsonb := '[]'::jsonb; v_r jsonb; v_a public.coach_assignments%rowtype;
  v_fb jsonb := '[]'::jsonb; v_check jsonb; v_draft private.titan_coach_review_drafts%rowtype; v_sent jsonb; v_prev jsonb; v_next text := 'none';
  v_dossier jsonb; v_source jsonb; v_planned boolean; v_n integer;
begin
  select p.username into v_name from public.profiles p where p.id = l.athlete_id;
  if not private.titan_coach_link_active(l.id) then
    return jsonb_build_object('link_id', l.id, 'name', v_name, 'link_state', 'paused', 'next', 'paused', 'actionable', false);
  end if;
  -- Proposals of the window, plus anything still waiting on a decision (V1.9.1 rows, without the long history and versions).
  for v_a in select * from public.coach_assignments a
              where a.link_id = l.id and a.status <> 'cancelled'
                and (coalesce(a.moved_date, a.planned_date) between p_week - 14 and p_week + 6 or a.status = 'proposed' or a.pending_change is not null)
              order by coalesce(a.moved_date, a.planned_date), a.created_at, a.id limit 40 loop
    v_r := private.titan_coach_followup_row(v_a, l, 'coach');
    if (v_r->>'effective_date')::date < p_week - 7 and not (v_r->>'coach_next' in ('wait', 'gap') and (v_r->>'seen')::boolean is not true) then continue; end if;
    v_items := v_items || jsonb_build_array((v_r - 'history' - 'accepted_version' - 'candidates') || jsonb_build_object(
      'feedback_count', (select count(*) from private.titan_coach_feedback f where f.assignment_id = v_a.id),
      'from_review', (select d.week_start from private.titan_coach_review_drafts d where d.assignment_id = v_a.id)));
  end loop;
  -- Adjustments of the V1.9.2 feedback: pending (the athlete decides) or answered since the past week began.
  select coalesce(jsonb_agg(jsonb_build_object('id', x->>'id', 'assignment_id', x#>>'{assignment,id}', 'assignment_title', x#>>'{assignment,title}',
           'created_at', x->>'created_at', 'kind', x#>>'{adjustment,kind}', 'state', x#>>'{adjustment,state}', 'answered_at', x#>>'{adjustment,answered_at}',
           'title', coalesce(x#>>'{adjustment,after,title}', x#>>'{adjustment,target,title}')) order by x->>'created_at'), '[]'::jsonb) into v_fb
    from (select private.titan_coach_feedback_row(f, l, 'coach') as x from private.titan_coach_feedback f
           where f.link_id = l.id and f.adjustment_state is not null and (f.adjustment_state = 'pending' or f.answered_at >= (p_week - 7)::timestamp at time zone 'Europe/Paris')
           order by f.created_at desc limit 10) q;
  -- The check-in of the past week, or of this week, ONLY if the athlete shared it with this link.
  select jsonb_strip_nulls(jsonb_build_object('week', c.week_start, 'scores', c.scores, 'note', c.note)) into v_check
    from private.titan_coach_checkins c where c.link_id = l.id and c.shared and c.week_start in (p_week - 7, p_week) order by c.week_start desc limit 1;
  select * into v_draft from private.titan_coach_review_drafts d where d.link_id = l.id and d.week_start = p_week and d.state = 'draft';
  select coalesce(jsonb_agg(jsonb_build_object('draft_id', d.id, 'assignment_id', d.assignment_id, 'sent_at', d.sent_at, 'title', a.title, 'planned_date', a.planned_date,
           'status', a.status) order by d.sent_at), '[]'::jsonb) into v_sent
    from private.titan_coach_review_drafts d left join public.coach_assignments a on a.id = d.assignment_id where d.link_id = l.id and d.week_start = p_week and d.state = 'sent';
  -- The decision on what the previous review sent comes back here.
  select coalesce(jsonb_agg(jsonb_build_object('assignment_id', a.id, 'title', a.title, 'planned_date', a.planned_date, 'status', a.status,
           'state', private.titan_coach_followup_row(a, l, 'coach')->>'state') order by d.sent_at), '[]'::jsonb) into v_prev
    from private.titan_coach_review_drafts d join public.coach_assignments a on a.id = d.assignment_id where d.link_id = l.id and d.week_start = p_week - 7 and d.state = 'sent';

  -- The next action, in this order: a gap to handle, a linked session without feedback, a prepared proposal to resume, a decision the
  -- athlete still owes, nothing planned for the coming week (prepare), or nothing to do.
  select e into v_dossier from jsonb_array_elements(v_items) with ordinality x(e, i)
   where e->>'coach_next' = 'gap' and (e->>'seen')::boolean is not true order by i limit 1;
  if v_dossier is not null then
    v_next := 'gap';
    v_source := case when v_dossier->>'state' = 'linked' and (v_dossier#>>'{linked,in_scope}')::boolean
                  then jsonb_build_object('kind', 'session', 'id', v_dossier->>'id', 'date', v_dossier->>'done_date')
                  else jsonb_build_object('kind', 'proposal', 'id', v_dossier->>'id', 'date', v_dossier->>'planned_date') end;
  end if;
  if v_next = 'none' then
    select e into v_dossier from jsonb_array_elements(v_items) with ordinality x(e, i)
     where e->>'state' = 'linked' and (e#>>'{linked,in_scope}')::boolean and (e->>'feedback_count')::integer = 0
       and (e->>'done_date')::date between p_week - 7 and least(p_week + 6, v_today) order by i limit 1;
    if v_dossier is not null then v_next := 'feedback'; v_source := jsonb_build_object('kind', 'session', 'id', v_dossier->>'id', 'date', v_dossier->>'done_date'); end if;
  end if;
  if v_next = 'none' and v_draft.id is not null then
    v_next := 'resume'; v_dossier := null; v_source := jsonb_build_object('kind', 'draft', 'id', v_draft.id, 'date', (v_draft.updated_at at time zone 'Europe/Paris')::date);
  end if;
  if v_next = 'none' then
    select e into v_dossier from jsonb_array_elements(v_items) with ordinality x(e, i) where e->>'coach_next' = 'wait' order by i limit 1;
    if v_dossier is not null then v_next := 'wait'; v_source := jsonb_build_object('kind', 'proposal', 'id', v_dossier->>'id', 'date', v_dossier->>'planned_date');
    elsif exists (select 1 from jsonb_array_elements(v_fb) e where e->>'state' = 'pending') then
      v_next := 'wait';
      select jsonb_build_object('kind', 'feedback', 'id', e->>'id', 'date', (e->>'created_at')::timestamptz::date) into v_source from jsonb_array_elements(v_fb) e where e->>'state' = 'pending' limit 1;
    end if;
  end if;
  if v_next = 'none' then
    v_planned := exists (select 1 from jsonb_array_elements(v_items) e where (e->>'effective_date')::date between p_week and p_week + 6 and e->>'state' <> 'declined')
                 or jsonb_array_length(v_sent) > 0;
    if not v_planned then
      v_next := 'prepare';
      -- Its source: the latest decision of the past week, else the shared check-in, else an empty dossier.
      select e into v_dossier from jsonb_array_elements(v_items) e where (e->>'effective_date')::date < p_week order by e->>'effective_date' desc limit 1;
      v_source := case when v_dossier is not null then jsonb_build_object('kind', 'proposal', 'id', v_dossier->>'id', 'date', v_dossier->>'planned_date')
                       when v_check is not null then jsonb_build_object('kind', 'checkin', 'date', v_check->>'week')
                       else jsonb_build_object('kind', 'empty') end;
    end if;
  end if;
  v_n := jsonb_array_length(v_items);
  return jsonb_build_object('link_id', l.id, 'name', v_name, 'link_state', 'active', 'revision', l.revision,
    'scope', jsonb_build_object('sport', l.sport, 'since_date', l.since_date, 'share_details', l.share_details, 'share_notes', l.share_notes),
    'next', v_next, 'actionable', v_next in ('gap', 'feedback', 'resume', 'prepare'), 'dossier', v_dossier, 'source', v_source,
    'items', v_items, 'item_count', v_n, 'adjustments', v_fb, 'checkin', v_check,
    'draft', case when v_draft.id is not null then private.titan_coach_review_draft_row(v_draft, l) else null end,
    'sent', v_sent, 'previous', v_prev,
    'key', left(md5(concat_ws('|', l.revision, v_next, v_dossier->>'id', v_dossier->>'state_key', v_draft.revision, jsonb_array_length(v_sent))), 16));
end;
$function$;
revoke all on function private.titan_coach_review_card(public.coach_links, date) from public, anon, authenticated;

create or replace function public.titan_coach_review_v1(p_action text, p_data jsonb default '{}'::jsonb)
returns jsonb language plpgsql security definer set search_path = '' set statement_timeout = '8s'
as $function$
declare
  v_uid uuid := auth.uid(); v_today date := (now() at time zone 'Europe/Paris')::date; v_now_week date; v_week date; v_link public.coach_links%rowtype;
  v_d private.titan_coach_review_drafts%rowtype; v_a public.coach_assignments%rowtype; v_tpl private.titan_coach_templates%rowtype;
  v_basis jsonb; v_content jsonb; v_text text; v_date date; v_only uuid; v_cards jsonb; v_filter text := coalesce(nullif(p_data->>'filter', ''), 'actionable'); v_id uuid; v_existing boolean := false;
begin
  if v_uid is null or not exists (select 1 from public.profiles where id = v_uid and is_suspended is not true) then raise exception 'AUTH_REQUIRED' using errcode = '42501'; end if;
  if jsonb_typeof(p_data) is distinct from 'object' or octet_length(p_data::text) > 8000 then raise exception 'INVALID_INPUT' using errcode = '22023'; end if;
  if not private.titan_flag_on('screens.coach_review') then raise exception 'FEATURE_DISABLED' using errcode = '42501'; end if;
  v_now_week := date_trunc('week', v_today)::date;
  begin
    v_week := coalesce(nullif(p_data->>'week', '')::date, v_now_week);
    v_only := nullif(p_data->>'link_id', '')::uuid;
    v_id := nullif(p_data->>'id', '')::uuid;
  exception when others then raise exception 'INVALID_INPUT' using errcode = '22023'; end;
  -- A review covers a Paris week (Monday), from 8 weeks back to the next week.
  if extract(isodow from v_week) <> 1 or v_week < v_now_week - 56 or v_week > v_now_week + 7 then raise exception 'INVALID_PERIOD' using errcode = '22023'; end if;

  -- ---- Coach: the review of a week, one card per unrevoked link (paused: name only), the actionable ones by default.
  if p_action = 'week' then
    if v_filter not in ('actionable', 'all') then raise exception 'INVALID_INPUT' using errcode = '22023'; end if;
    select coalesce(jsonb_agg(c order by case c->>'next' when 'gap' then 0 when 'feedback' then 1 when 'resume' then 2 when 'prepare' then 3 when 'wait' then 4 when 'none' then 5 else 6 end,
                              lower(coalesce(c->>'name', '')), c->>'link_id'), '[]'::jsonb) into v_cards
      from (select private.titan_coach_review_card(l, v_week) as c from public.coach_links l
             where l.coach_id = v_uid and l.revoked_at is null and (v_only is null or l.id = v_only)
             order by l.accepted_at, l.id limit 60) q;
    return jsonb_build_object('owner', v_uid, 'today', v_today, 'week', v_week, 'week_end', v_week + 6, 'past', jsonb_build_array(v_week - 7, v_week - 1),
      'current_week', v_now_week, 'filter', v_filter,
      'counts', jsonb_build_object('athletes', jsonb_array_length(v_cards),
        'actionable', (select count(*) from jsonb_array_elements(v_cards) e where (e->>'actionable')::boolean),
        'gap', (select count(*) from jsonb_array_elements(v_cards) e where e->>'next' = 'gap'),
        'feedback', (select count(*) from jsonb_array_elements(v_cards) e where e->>'next' = 'feedback'),
        'resume', (select count(*) from jsonb_array_elements(v_cards) e where e->>'next' = 'resume'),
        'prepare', (select count(*) from jsonb_array_elements(v_cards) e where e->>'next' = 'prepare'),
        'wait', (select count(*) from jsonb_array_elements(v_cards) e where e->>'next' = 'wait'),
        'none', (select count(*) from jsonb_array_elements(v_cards) e where e->>'next' = 'none'),
        'paused', (select count(*) from jsonb_array_elements(v_cards) e where e->>'next' = 'paused')),
      'cards', coalesce((select jsonb_agg(e order by i) from jsonb_array_elements(v_cards) with ordinality x(e, i)
                          where v_filter = 'all' or (e->>'actionable')::boolean or e->>'next' = 'paused'), '[]'::jsonb));
  end if;

  if p_action not in ('prepare', 'send', 'discard') then raise exception 'INVALID_ACTION' using errcode = '22023'; end if;

  -- ---- Writes. Lock order of the portal: the sharing link first, then the draft.
  if p_action = 'prepare' then
    select * into v_link from public.coach_links where id = v_only and revoked_at is null and (coach_id = v_uid or athlete_id = v_uid) for update;
  else
    select l.* into v_link from public.coach_links l join private.titan_coach_review_drafts d on d.link_id = l.id
     where d.id = v_id and l.revoked_at is null and (l.coach_id = v_uid or l.athlete_id = v_uid) for update of l;
  end if;
  if not found then raise exception 'SHARING_UNAVAILABLE' using errcode = '42501'; end if;
  if v_link.coach_id <> v_uid then raise exception 'COACH_ONLY' using errcode = '42501'; end if;
  if p_action <> 'discard' and not private.titan_coach_link_active(v_link.id) then raise exception 'COACH_CAPACITY_PAUSED' using errcode = '42501'; end if;
  perform private.titan_rate_limit(v_uid, 'coach_followup', 120);

  if p_action = 'prepare' then
    select * into v_d from private.titan_coach_review_drafts where link_id = v_link.id and week_start = v_week and state = 'draft' for update;
    -- Preparing again without the draft's revision (another tab, a reload after an interruption) resumes the draft: nothing is overwritten.
    if v_d.id is not null and p_data->>'revision' is null then
      return jsonb_build_object('ok', true, 'resumed', true, 'draft', private.titan_coach_review_draft_row(v_d, v_link));
    end if;
    if v_d.id is not null and v_d.revision is distinct from (p_data->>'revision')::integer then raise exception 'COACH_CONFLICT'; end if;
    if v_d.id is null and p_data->>'revision' is not null then raise exception 'COACH_CONFLICT'; end if;
    -- The basis: a template of this coach, a proposal of this link, the draft's own basis, or a blank page.
    if nullif(p_data->>'template_id', '') is not null then
      begin select * into v_tpl from private.titan_coach_templates where id = (p_data->>'template_id')::uuid and coach_id = v_uid;
      exception when others then raise exception 'INVALID_INPUT' using errcode = '22023'; end;
      if v_tpl.id is null then raise exception 'TEMPLATE_UNAVAILABLE' using errcode = '22023'; end if;
      v_basis := jsonb_build_object('kind', 'template', 'id', v_tpl.id, 'title', v_tpl.title,
                   'base', jsonb_build_object('title', v_tpl.title, 'sport', v_tpl.sport, 'instructions', v_tpl.instructions));
    elsif nullif(p_data->>'from_id', '') is not null then
      begin select * into v_a from public.coach_assignments where id = (p_data->>'from_id')::uuid and link_id = v_link.id;
      exception when others then raise exception 'INVALID_INPUT' using errcode = '22023'; end;
      if v_a.id is null then raise exception 'INVALID_INPUT' using errcode = '22023'; end if;
      v_basis := jsonb_build_object('kind', 'proposal', 'id', v_a.id, 'title', v_a.title,
                   'base', jsonb_build_object('title', v_a.title, 'sport', v_a.sport, 'instructions', v_a.instructions));
    elsif v_d.id is not null then v_basis := v_d.basis;
    else v_basis := jsonb_build_object('kind', 'blank', 'base', '{}'::jsonb);
    end if;
    v_content := coalesce(case when v_d.id is not null and v_d.basis->>'id' is not distinct from v_basis->>'id' then v_d.content end, v_basis->'base');
    if p_data ? 'title' then v_content := v_content || jsonb_build_object('title', p_data->>'title'); end if;
    if p_data ? 'sport' then v_content := v_content || jsonb_build_object('sport', p_data->>'sport'); end if;
    if p_data ? 'planned_date' then v_content := v_content || jsonb_build_object('planned_date', p_data->>'planned_date'); end if;
    if p_data ? 'instructions' then v_content := v_content || jsonb_build_object('instructions', p_data->>'instructions'); end if;
    -- The portal's rules for a proposal.
    v_text := left(regexp_replace(btrim(coalesce(v_content->>'title', '')), '[[:cntrl:]<>]', '', 'g'), 100);
    if v_text = '' then raise exception 'BAD_TITLE' using errcode = '22023'; end if;
    v_content := v_content || jsonb_build_object('title', v_text);
    if not exists (select 1 from public.sports s where s.id = v_content->>'sport' and coalesce(s.is_active, true)) then raise exception 'SPORT_UNKNOWN' using errcode = '22023'; end if;
    if nullif(v_content->>'planned_date', '') is not null then
      begin v_date := (v_content->>'planned_date')::date; exception when others then raise exception 'INVALID_PERIOD' using errcode = '22023'; end;
      if v_date < v_today or v_date > current_date + 366 then raise exception 'INVALID_PERIOD' using errcode = '22023'; end if;
      v_content := v_content || jsonb_build_object('planned_date', v_date);
    else v_content := v_content - 'planned_date';
    end if;
    v_content := v_content || jsonb_build_object('instructions', left(regexp_replace(coalesce(v_content->>'instructions', ''), '[\x01-\x09\x0b-\x1f\x7f<>]', '', 'g'), 2000));
    if v_d.id is null then
      insert into private.titan_coach_review_drafts (link_id, coach_id, week_start, basis, content) values (v_link.id, v_uid, v_week, v_basis, v_content) returning * into v_d;
    else
      update private.titan_coach_review_drafts set basis = v_basis, content = v_content, revision = revision + 1, updated_at = now() where id = v_d.id returning * into v_d;
    end if;
    return jsonb_build_object('ok', true, 'resumed', false, 'draft', private.titan_coach_review_draft_row(v_d, v_link));
  end if;

  select * into v_d from private.titan_coach_review_drafts where id = v_id and link_id = v_link.id and coach_id = v_uid for update;
  if not found then raise exception 'SHARING_UNAVAILABLE' using errcode = '42501'; end if;

  if p_action = 'discard' then
    if v_d.state <> 'draft' then raise exception 'INVALID_TRANSITION' using errcode = '22023'; end if;
    if v_d.revision is distinct from (p_data->>'revision')::integer then raise exception 'COACH_CONFLICT'; end if;
    update private.titan_coach_review_drafts set state = 'discarded', revision = revision + 1, updated_at = now() where id = v_d.id returning * into v_d;
    return jsonb_build_object('ok', true, 'draft', private.titan_coach_review_draft_row(v_d, v_link));
  end if;

  -- ---- send: the coach's explicit action on the draft they previewed (its revision). Once only.
  if v_d.state = 'sent' then
    select * into v_a from public.coach_assignments where id = v_d.assignment_id;
    return jsonb_build_object('ok', true, 'already', true, 'draft', private.titan_coach_review_draft_row(v_d, v_link),
      'assignment', case when v_a.id is not null then private.titan_coach_followup_row(v_a, v_link, 'coach') - 'history' else null end);
  end if;
  if v_d.state <> 'draft' then raise exception 'INVALID_TRANSITION' using errcode = '22023'; end if;
  if v_d.revision is distinct from (p_data->>'revision')::integer then raise exception 'COACH_CONFLICT'; end if;
  v_content := v_d.content;
  begin v_date := (v_content->>'planned_date')::date; exception when others then raise exception 'INVALID_PERIOD' using errcode = '22023'; end;
  if v_date is null or v_date < v_today or v_date > current_date + 366 then raise exception 'INVALID_PERIOD' using errcode = '22023'; end if;
  if not exists (select 1 from public.sports s where s.id = v_content->>'sport' and coalesce(s.is_active, true)) then raise exception 'SPORT_UNKNOWN' using errcode = '22023'; end if;
  -- The same session already open on this link (sent before an interruption, prepared twice, or proposed by the usual form): never a
  -- duplicate. Not yet tied to a review: this draft is attached to it. Already sent by another draft: this one is set aside.
  select * into v_a from public.coach_assignments a where a.link_id = v_link.id and a.status in ('proposed', 'accepted') and a.title = v_content->>'title'
     and a.sport = v_content->>'sport' and a.planned_date = v_date and a.instructions = coalesce(v_content->>'instructions', '')
   order by a.created_at limit 1;
  if v_a.id is not null and exists (select 1 from private.titan_coach_review_drafts x where x.assignment_id = v_a.id) then
    update private.titan_coach_review_drafts set state = 'discarded', revision = revision + 1, updated_at = now() where id = v_d.id returning * into v_d;
    return jsonb_build_object('ok', true, 'already', true, 'code', 'ALREADY_PROPOSED', 'draft', private.titan_coach_review_draft_row(v_d, v_link),
      'assignment', private.titan_coach_followup_row(v_a, v_link, 'coach') - 'history');
  end if;
  v_existing := v_a.id is not null;
  if v_a.id is null then
    if (select count(*) from public.coach_assignments where link_id = v_link.id) >= 500 then raise exception 'ASSIGNMENT_LIMIT' using errcode = '22023'; end if;
    insert into public.coach_assignments (link_id, title, sport, planned_date, instructions)
      values (v_link.id, v_content->>'title', v_content->>'sport', v_date, coalesce(v_content->>'instructions', '')) returning * into v_a;
  end if;
  update public.coach_assignments set history = private.titan_coach_history_cap(history || jsonb_build_array(jsonb_build_object('k', 'from_review', 'at', now(), 'week', v_d.week_start)))
   where id = v_a.id returning * into v_a;
  update private.titan_coach_review_drafts set state = 'sent', assignment_id = v_a.id, sent_at = now(), revision = revision + 1, updated_at = now() where id = v_d.id returning * into v_d;
  return jsonb_build_object('ok', true, 'already', v_existing, 'code', case when v_existing then 'ALREADY_PROPOSED' else null end, 'draft', private.titan_coach_review_draft_row(v_d, v_link),
    'assignment', private.titan_coach_followup_row(v_a, v_link, 'coach') - 'history');
end;
$function$;
revoke all on function public.titan_coach_review_v1(text, jsonb) from public, anon;
grant execute on function public.titan_coach_review_v1(text, jsonb) to authenticated;

-- ---- The export: the body of 20261202090000, plus the coach's review drafts (their own working content, no measure of the athlete).
create or replace function private.titan_export_extras_v1(p_uid uuid)
returns jsonb language sql stable security definer set search_path = '' as $$
  select private.titan_export_extras_before_cadence_v1(p_uid) || jsonb_build_object(
    'cadenceWeekClaims', coalesce((
      select jsonb_agg(jsonb_build_object('week', c.week_start, 'days', c.days, 'target', c.target, 'credits', c.credits, 'claimed_at', c.claimed_at) order by c.week_start)
      from private.titan_cadence_claims c where c.user_id = p_uid), '[]'::jsonb),
    'timeCapsules', coalesce((
      select jsonb_agg(jsonb_build_object('message', t.message, 'months', t.months, 'deliver_on', t.deliver_on, 'written_minutes', t.written_minutes,
        'written_days', t.written_days, 'created_at', t.created_at, 'opened_at', t.opened_at) order by t.created_at)
      from private.titan_time_capsules t where t.user_id = p_uid), '[]'::jsonb),
    'lifeChapters', coalesce((
      select jsonb_agg(jsonb_build_object('title', l.title, 'starts_on', l.starts_on, 'ends_on', l.ends_on, 'created_at', l.created_at) order by l.starts_on)
      from private.titan_life_chapters l where l.user_id = p_uid), '[]'::jsonb),
    'coachFeedback', coalesce((
      select jsonb_agg(jsonb_build_object('link_id', f.link_id, 'assignment_id', f.assignment_id, 'message_id', f.message_id, 'session_day', f.session_day,
        'adjustment', f.adjustment, 'adjustment_state', f.adjustment_state, 'answered_at', f.answered_at, 'read_at', f.read_at, 'created_at', f.created_at) order by f.created_at)
      from private.titan_coach_feedback f join public.coach_links l on l.id = f.link_id where p_uid in (l.coach_id, l.athlete_id)), '[]'::jsonb),
    'coachReviewDrafts', coalesce((
      select jsonb_agg(jsonb_build_object('link_id', d.link_id, 'week', d.week_start, 'state', d.state, 'basis', d.basis - 'base', 'content', d.content,
        'assignment_id', d.assignment_id, 'created_at', d.created_at, 'sent_at', d.sent_at) order by d.created_at)
      from private.titan_coach_review_drafts d where d.coach_id = p_uid), '[]'::jsonb));
$$;
revoke all on function private.titan_export_extras_v1(uuid) from public, anon, authenticated;

-- Measure (team only, no identifier): drafts by state and basis, proposals sent from a review and the athlete's answer, and the complete
-- cycles over two weeks (a proposal sent from the review of week W, answered, then a new one sent from the review of week W + 1).
create or replace function private.titan_coach_review_measure()
returns jsonb language sql stable security definer set search_path = ''
as $function$
  select jsonb_build_object(
    'drafts', (select jsonb_object_agg(s, n) from (select state s, count(*) n from private.titan_coach_review_drafts group by 1) x),
    'fromTemplate', (select count(*) from private.titan_coach_review_drafts where state = 'sent' and basis->>'kind' = 'template'),
    'sent', (select count(*) from private.titan_coach_review_drafts where state = 'sent'),
    'answered', (select count(*) from private.titan_coach_review_drafts d join public.coach_assignments a on a.id = d.assignment_id
                  where d.state = 'sent' and a.status in ('accepted', 'declined', 'completed')),
    'cyclesEligible', (select count(*) from private.titan_coach_review_drafts d where d.state = 'sent'
                        and d.week_start <= date_trunc('week', (now() at time zone 'Europe/Paris')::date)::date - 7),
    'cyclesComplete', (select count(*) from private.titan_coach_review_drafts d join public.coach_assignments a on a.id = d.assignment_id
                        where d.state = 'sent' and a.status in ('accepted', 'declined', 'completed')
                          and exists (select 1 from private.titan_coach_review_drafts n where n.link_id = d.link_id and n.state = 'sent' and n.week_start = d.week_start + 7)))
$function$;
revoke all on function private.titan_coach_review_measure() from public, anon, authenticated;

notify pgrst, 'reload schema';
-- <<< repository file
insert into supabase_migrations.schema_migrations (version, name) values ('20261130101300', 'coach_weekly_review');
commit;
